<style>
.ptm-page{color:#25313c;font-family:Inter,Arial,sans-serif}.ptm-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:20px}.ptm-head h1{font-size:23px;font-weight:700;color:#123b5d;margin:0}.ptm-sub{font-size:13px;color:#64748b;margin-top:6px}.ptm-actions{display:flex;gap:8px;flex-wrap:wrap}.ptm-btn{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:0 15px;border:1px solid #cbd5e1;border-radius:9px;background:#fff;color:#123b5d;text-decoration:none;font-size:13px;font-weight:600;cursor:pointer}.ptm-btn.primary{background:#123b5d;color:#fff;border-color:#123b5d}.ptm-btn.danger{color:#dc2626}.ptm-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.ptm-kpi,.ptm-panel{background:#fff;border:1px solid #d5deea;border-radius:14px;padding:17px}.ptm-kpi small{display:block;color:#64748b;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.35px}.ptm-kpi strong{display:block;color:#123b5d;font-size:26px;margin:9px 0 3px}.ptm-kpi span{font-size:11px;color:#64748b}.ptm-panel{margin-top:16px}.ptm-panel h3{font-size:15px;color:#123b5d;margin:0 0 14px;font-weight:700}.ptm-table{width:100%;border-collapse:collapse;font-size:12px}.ptm-table th{background:#f8fafc;color:#64748b;text-align:left;font-size:10px;text-transform:uppercase;letter-spacing:.3px;padding:12px;border-bottom:1px solid #dbe3ed}.ptm-table td{padding:12px;border-bottom:1px solid #e2e8f0;vertical-align:middle}.ptm-badge{display:inline-block;border-radius:20px;padding:4px 9px;font-size:10px;font-weight:700;text-transform:capitalize}.ptm-pending{background:#fff3cd;color:#a16207}.ptm-confirmed{background:#dbeafe;color:#1d4ed8}.ptm-completed{background:#dcfce7;color:#15803d}.ptm-cancelled{background:#fee2e2;color:#b91c1c}.ptm-rescheduled{background:#f3e8ff;color:#7e22ce}.ptm-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.ptm-field label{display:block;font-size:12px;font-weight:650;margin-bottom:7px;color:#334155}.ptm-field input,.ptm-field select,.ptm-field textarea,.ptm-filter input,.ptm-filter select{width:100%;box-sizing:border-box;border:1px solid #cbd5e1;border-radius:9px;padding:11px 12px;font:13px Inter,Arial;color:#25313c;background:#fff}.ptm-field textarea{min-height:90px;resize:vertical}.ptm-field.full{grid-column:1/-1}.ptm-errors{background:#fef2f2;border:1px solid #fecaca;color:#991b1b;padding:12px;border-radius:9px;margin-bottom:15px;font-size:13px}.ptm-calendar{display:grid;grid-template-columns:64px repeat(7,minmax(78px,1fr));gap:6px;overflow-x:auto}.ptm-day{background:#f1f5f9;border-radius:8px;padding:10px 4px;text-align:center;color:#123b5d;font-size:11px;font-weight:700}.ptm-day.today{background:#123b5d;color:#fff}.ptm-time{font-size:10px;color:#64748b;padding:10px 2px}.ptm-slot{min-height:42px;border:1px solid #dbe3ed;border-radius:8px;background:#fff;padding:5px;font-size:9px;text-align:center;color:#94a3b8}.ptm-slot.filled{background:#dbeafe;border-color:#93c5fd;color:#1e40af}.ptm-slot.filled.completed{background:#dcfce7;border-color:#86efac;color:#166534}.ptm-slot.filled.pending{background:#fef3c7;border-color:#fcd34d;color:#92400e}.ptm-columns{display:grid;grid-template-columns:1.1fr .9fr;gap:14px}.ptm-meeting{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:10px;background:#f8fafc;border-radius:9px;margin-bottom:8px;font-size:12px}.ptm-muted{color:#64748b;font-size:11px}.ptm-inline{display:flex;gap:6px;flex-wrap:wrap}.ptm-filter{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}.ptm-filter input{max-width:260px}.ptm-filter select{max-width:180px}.ptm-empty{color:#94a3b8;text-align:center;padding:20px;font-size:12px}
@media(max-width:900px){.ptm-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.ptm-columns{grid-template-columns:1fr}.ptm-head{flex-direction:column}.ptm-fields{grid-template-columns:1fr}}
</style>
